	hrow("record", st.Glue)
	hrow("submit+fence", st.Submit)
	hrow("sample", hp.sample)
	hrow("detokenize", hp.detok)
	hrow("emit", hp.emit)
	rest := wall - st.Gather - st.Glue - st.Submit - hp.sample - hp.detok - hp.emit
	hrow("unattributed", rest)

