python3 - <<'PY'
p='llm/gpu_attn.go'
s=open(p).read()
i=s.index("// attnSplits is how many ways this pass cuts the key axis")
j=s.index("func (g *AttnGPU) graph(layer int)")
new = '''// attnSplits is how many ways this pass cuts the key axis, and 1 for the
// unsplit kernel.
//
// **The question it answers is how long one wave's walk is**, not how much
// work the dispatch has. The grid is (query blocks, heads), every workgroup is
// a single wave, and 24 of them fit on this device's 40 compute units at once
// — so a decode step's attention costs one wave walking every key block of the
// cache, and nothing about the other 23 changes that. Measured: cutting the
// grid from 24 workgroups to 2, which is a twelfth of the work and a twelfth
// of the traffic, moved the dispatch 1.00x at every depth. Only cutting the
// walk moves it.
//
// So the split is taken when the walk is the cost: a batch no wider than one
// query tile, which is the decode regime. Past that the query axis already
// fills the grid — at 512 rows it dispatches 768 workgroups — and the
// unsplit kernel is what runs.
//
// **The count comes from the cache and not from the depth, and that is
// deliberate.** P7's whole finding was that three kernels charged `nKV` where
// they owed the context, so reading `nKV` here wants a reason. It is this: a
// decode step's command buffer is recorded once and replayed byte for byte
// every token (P1c), so a slice count that moved with `past` would either
// stale the recording or have to invalidate it every few tokens. What `nKV`
// decides here is only **how many slices** — a constant, a few hundred
// workgroups either way — while how many *cells* each slice walks is
// `SEQ_PAST`, read from the arena at dispatch time. A slice with no block in
// it falls straight through to its epilogue and writes the combine's
// identity, so a shallow cache in a deep arena costs the empty slices' stores
// and nothing that grows.
//
// LLM_ATTN_SPLITS overrides: 1 is the unsplit kernel, which is the control
// arm this was measured against, and a larger number pins the count.
func (g *AttnGPU) attnSplits(av attnVariant) int {
	if g.rows > av.rows || g.rows > attnSplitMaxRows {
		return 1
	}
	max := attnMaxSplits
	if n, err := strconv.Atoi(os.Getenv("LLM_ATTN_SPLITS")); err == nil && n >= 1 {
		max = n
	}
	blocks := roundUpInt(g.nKV, av.keys) / av.keys
	if blocks < 2*attnSplitBlocks {
		return 1
	}
	return minInt(blocks/attnSplitBlocks, max)
}

