// that differs between them.
func TestAttnGPUSplitMatchesUnsplit(t *testing.T) {
	g, tr, c, nTok, done := attnGPU4k(t)
	defer done()
	src, err := tr.Get("hc_mixed-3", 0)
	if err != nil {
		t.Fatal(err)
