	for i := from; i < len(got); i++ {
		d := math.Abs(float64(got[i]) - float64(want[i]))
		maxAbs = math.Max(maxAbs, d)
		if a := math.Abs(float64(want[i])); a > 1e-3 {
			maxRel = math.Max(maxRel, d/a)
		}
		sum2 += d * d
		ref2 += float64(want[i]) * float64(want[i])
	}
